const D = { energy: .6, scale: 1, speed: 1, density: .55, motif: 'fleur', hue: 44, x: .5, y: .5, style: 'gilt', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// DIAPER FIELD -- the small-scale seme field of Gothic illumination: a raised gilt
// trellis of lozenges with a motif (fleur-de-lis, cross-crosslet, rose, quatrefoil)
// stamped in every cell, on a jewel ground. The lattice is fixed; a soft pool of
// light drifts across it on incommensurate rates, so the gilding gleams cell by
// cell and the strict symmetry never reads frozen. Illuminated gilt, incised stone
// grisaille, tin-glazed majolica, or a cyan schematic.
// -----------------------------------------------------------------------------

const u = Math.min(width, height);
const sd = (P.seed | 0);
const fr = i => { let h = (Math.imul((i ^ sd) | 0, 374761393) + 0x9e3779b9) | 0; h = Math.imul(h ^ (h >>> 15), 668265263); h ^= h >>> 13; return ((h >>> 0) % 100000) / 100000; };

const st = P.style;
let grd, barLo, barHi, mLo, mHi, mEdge, stone = false, line = false;
if (st === 'grisaille') { grd = [36, 8, 44]; barLo = [34, 8, 26]; barHi = [34, 4, 66]; mLo = [34, 6, 34]; mHi = [34, 3, 62]; mEdge = [34, 2, 80]; stone = true; }
else if (st === 'majolica') { grd = [220, 62, 26]; barLo = [42, 40, 40]; barHi = [46, 30, 88]; mLo = [30, 70, 46]; mHi = [40, 60, 82]; mEdge = [48, 30, 100]; }
else if (st === 'blueprint') { grd = [220, 64, 14]; barLo = [200, 55, 38]; barHi = [190, 45, 78]; mLo = [205, 50, 30]; mHi = [195, 45, 62]; mEdge = [188, 40, 92]; line = true; }
else { grd = [(fr(99) > 0.5 ? 220 : 2), 66, 24]; barLo = [(P.hue - 8 + 360) % 360, 70, 30]; barHi = [(P.hue + 6) % 360, 52, 88]; mLo = [(P.hue - 4 + 360) % 360, 72, 34]; mHi = [(P.hue + 6) % 360, 50, 92]; mEdge = [(P.hue + 12) % 360, 30, 100]; } // gilt

// ---- adaptive high-res field buffer -----------------------------------------
const BW = Math.max(360, Math.min(720, Math.round(width / 2.2)));
const BH = Math.max(120, Math.round(BW * height / width));
const nx = 4 + Math.round(P.density * 5);                 // cells across
const key = BW + 'x' + BH + '|' + P.seed + '|' + nx + '|' + st + '|' + P.motif + '|' + P.scale.toFixed(2);
if (S.key !== key || !S.field) {
  S.key = key;
  const g = createGraphics(BW, BH); g.colorMode(HSB, 360, 100, 100, 100); g.noStroke();
  g.background(grd[0], grd[1], grd[2]);
  for (let i = 0; i < 2400; i++) { g.fill(grd[0], grd[1] + 6, grd[2] + (fr(i) - 0.4) * 14, 20); g.rect(fr(i * 2 + 1) * BW, fr(i * 2 + 2) * BH, 1.4, 1.4); }
  const cw = BW / nx / P.scale, ch = cw;                   // square lozenge cells (rotated 45)
  const rows = Math.ceil(BH / ch) + 2, colsN = Math.ceil(BW / cw) + 2;

  function stampMotif(cx, cy, r) {
    const m = P.motif;
    if (line) { g.noFill(); g.stroke(mHi[0], mHi[1], mHi[2], 80); g.strokeWeight(Math.max(0.6, r * 0.06)); }
    else { g.noStroke(); }
    if (m === 'cross') {
      const arm = r * 0.7, wt = r * 0.24;
      for (const rot of [0, 1]) { g.push(); g.translate(cx, cy); if (rot) g.rotate(1.5708); if (!line) { g.fill(mLo[0], mLo[1], mLo[2]); g.rect(-wt / 2 + 1, -arm + 1, wt, arm * 2); g.fill(mHi[0], mHi[1], mHi[2]); } g.rectMode(g.CENTER); g.rect(0, 0, wt, arm * 2); if (line) g.rect(0, 0, wt, arm * 2); g.pop(); }
      // crosslets
      if (!line) { g.fill(mEdge[0], mEdge[1], mEdge[2], 70); g.ellipse(cx, cy, r * 0.24, r * 0.24); }
    } else if (m === 'rose') {
      for (let p = 0; p < 5; p++) { const a = -1.5708 + p * 1.2566; if (!line) g.fill(mLo[0], mLo[1], mLo[2]); g.ellipse(cx + Math.cos(a) * r * 0.42, cy + Math.sin(a) * r * 0.42, r * 0.6, r * 0.6); }
      if (!line) { g.fill(mHi[0], mHi[1], mHi[2]); g.ellipse(cx, cy, r * 0.6, r * 0.6); g.fill(mEdge[0], mEdge[1], mEdge[2], 80); g.ellipse(cx, cy, r * 0.24, r * 0.24); }
      else { g.ellipse(cx, cy, r * 0.6, r * 0.6); }
    } else if (m === 'quatrefoil') {
      for (let p = 0; p < 4; p++) { const a = p * 1.5708; if (!line) g.fill(mLo[0], mLo[1], mLo[2]); g.ellipse(cx + Math.cos(a) * r * 0.4, cy + Math.sin(a) * r * 0.4, r * 0.62, r * 0.62); }
      if (!line) { g.fill(mHi[0], mHi[1], mHi[2]); g.ellipse(cx, cy, r * 0.5, r * 0.5); }
    } else { // fleur-de-lis
      const s = r * 1.5;
      g.push(); g.translate(cx, cy);
      if (!line) g.fill(mLo[0], mLo[1], mLo[2]);
      g.beginShape(); g.vertex(0, -s * 0.55); g.bezierVertex(s * 0.2, -s * 0.5, s * 0.15, -s * 0.02, 0, s * 0.12); g.bezierVertex(-s * 0.15, -s * 0.02, -s * 0.2, -s * 0.5, 0, -s * 0.55); g.endShape(g.CLOSE);
      for (const sgn of [-1, 1]) { g.beginShape(); g.vertex(0, -s * 0.02); g.bezierVertex(sgn * s * 0.36, -s * 0.26, sgn * s * 0.42, s * 0.06, sgn * s * 0.18, s * 0.2); g.bezierVertex(sgn * s * 0.12, s * 0.04, sgn * s * 0.05, -s * 0.02, 0, -s * 0.02); g.endShape(g.CLOSE); }
      if (!line) { g.fill(mHi[0], mHi[1], mHi[2], 80); g.beginShape(); g.vertex(0, -s * 0.5); g.bezierVertex(s * 0.1, -s * 0.42, s * 0.08, -s * 0.05, 0, s * 0.06); g.bezierVertex(-s * 0.08, -s * 0.05, -s * 0.1, -s * 0.42, 0, -s * 0.5); g.endShape(g.CLOSE); }
      g.rectMode(g.CENTER); if (!line) g.fill(mLo[0], mLo[1], mLo[2]); g.rect(0, s * 0.16, s * 0.46, s * 0.09);
      g.pop();
    }
  }

  // raised gilt trellis: diagonal bars both directions
  function bars(dir) {
    for (let d = -rows; d < colsN + rows; d++) {
      // shadow then highlight for bevel
      if (!line) { g.stroke(barLo[0], barLo[1], barLo[2], 90); g.strokeWeight(cw * 0.1); g.line(d * cw + 1.5, -ch + 1.5, (d - rows) * cw * dir + 1.5, (rows) * ch + 1.5); }
      g.stroke(barHi[0], barHi[1], Math.min(100, barHi[2]), line ? 70 : 100); g.strokeWeight(cw * (line ? 0.02 : 0.06));
      g.line(d * cw, -ch, (d - rows) * cw * dir, (rows) * ch);
    }
  }
  g.push(); g.strokeCap(g.SQUARE); bars(1); bars(-1); g.pop();

  // motifs at cell centres (rotated-grid lozenge centres)
  const r = cw * 0.34;
  for (let ry = -1; ry < rows; ry++) for (let cxi = -1; cxi < colsN; cxi++) {
    const mx = cxi * cw + (ry % 2 ? cw * 0.5 : 0), my = ry * ch * 0.5;
    if (my < -ch || my > BH + ch) continue;
    stampMotif(mx, my, r);
  }
  S.field = g;
}

// ---- animation: pool of light drifts on incommensurate rates ----------------
const sp = 0.3 + P.speed * 0.9;
const glow = 0.5 + P.energy * 1.0 + A.rms * 0.25;
const px = width * (0.5 + 0.34 * Math.sin(K.t * 0.19 * sp) + 0.12 * Math.sin(K.t * 0.47 * sp + 1.3));
const py = height * (0.5 + 0.30 * Math.cos(K.t * 0.23 * sp) + 0.10 * Math.sin(K.t * 0.61 * sp));
const pr = u * (0.62 + 0.12 * Math.sin(K.t * 0.33 * sp)) * (0.9 + P.scale * 0.1);

push();
image(S.field, 0, 0, width, height);
const dc = drawingContext;
// bright pool (ADD)
blendMode(ADD);
let gg = dc.createRadialGradient(px, py, pr * 0.05, px, py, pr);
gg.addColorStop(0, 'rgba(255,242,206,' + Math.min(0.55, 0.34 * glow) + ')');
gg.addColorStop(0.5, 'rgba(255,238,200,' + Math.min(0.3, 0.16 * glow) + ')');
gg.addColorStop(1, 'rgba(255,240,200,0)');
dc.save(); dc.fillStyle = gg; dc.fillRect(0, 0, width, height); dc.restore();
// gentle shadow away from the pool (MULT vignette that follows the light -> deepens contrast)
blendMode(MULTIPLY);
let vg = dc.createRadialGradient(px, py, pr * 0.3, px, py, pr * 1.7);
vg.addColorStop(0, 'rgba(255,255,255,1)');
vg.addColorStop(1, 'rgba(120,110,140,' + (stone ? 0.7 : 0.82) + ')');
dc.save(); dc.fillStyle = vg; dc.fillRect(0, 0, width, height); dc.restore();
blendMode(BLEND);
pop();

blendMode(BLEND);
if (P.alpha < 100) { push(); noStroke(); rectMode(CORNER); fill(grd[0], grd[1], grd[2], 100 - Math.max(0, Math.min(100, P.alpha))); rect(0, 0, width, height); pop(); }
drawingContext.shadowBlur = 0;
